err=$(ARCHIVE=$t bash tools/purge-archive 2>&1 >/dev/null); [ "$err" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $err"; fail=1; }
rm -f "$t"; exit $fail

