out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
t2=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t2"
out2=$(ARCHIVE=$t2 bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same date) failed"; fail=1; }
[ "$out2" = "purged 1 row(s) before 2025-01-01 from $t2" ] || { echo "same-date output: $out2"; fail=1; }
[ "$(grep -vc '^#' "$t2")" = 2 ] && grep -q 'z$' "$t2" && grep -q 'y$' "$t2" || { echo "a row dated on the cutoff was deleted"; fail=1; }
rm -f "$t2"
