#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
t2=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tsame\n' > "$t2"
ARCHIVE=$t2 bash tools/purge-archive --before 2025-01-01 >/dev/null || { echo "purge --before failed (same date)"; fail=1; }
[ "$(grep -vc '^#' "$t2")" = 1 ] && grep -q 'same$' "$t2" || { echo "a row dated on the cutoff was deleted"; fail=1; }
rm -f "$t2"
t3=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n' > "$t3"
ARCHIVE=$t3 bash tools/purge-archive --before 2025-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a month out of range should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t3")" = 1 ] || { echo "an out-of-range date deleted rows"; fail=1; }
rm -f "$t3"
u=$(bash tools/purge-archive 2>&1); [ "$u" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage: $u"; fail=1; }
rm -f "$t"; exit $fail

